import re
import six
from collections import defaultdict


class RadioOutputParser(object):
    def __init__(self):
        self.re_trx_id = re.compile(
            r"^ret (?P<antenna>/ant\d+_hran_radio) get.*done ok (?P<trx_ids>\"[L|W|G].*\")"
        )
        self.re_power = re.compile(
            r"^ret.*(?P<tx_ids>\"[L|W|G].*\")\s*==>(.*\"\s*(?P<power>\d{1,}\.\d{1,}){1,}$|.*)"
        )
        self.re_rx_power = re.compile(
            r"^ret.*(?P<rx_ids>\"[L|W|G].*\")\s*==>(.*\"\s*(?P<power>-?\d{1,}\.\d{1,}){1,}$|.*)"
        )
        self.re_carrier = re.compile(
            (r'^ret /(?P<antenna>ant\d+)_hran_radio action read_config \"(?P<trx_ids>[L|W|G].*)\" ==> '
             r'done ok POWER (?P<power>\d+) ALLOC_POWER (?P<alloc_power>\d+) FREQUENCY (?P<frequency>\d+) BANDWIDTH (?P<bandwidth>\d+) '
             r'STATE (?P<state>\w+) DATA_MODE (?P<data_mode>\w+)')
        )
        self.re_lna_device = re.compile(
            r"^ret / action create LnaDevice /(?P<lna_nr>lna\d) /rf/rx(?P<rx_nr>\d) ==> (done ok.*|error 0x09 \"Path already taken\")"
        )
        self.re_gain_target = re.compile(
            r"^ret /.*get gain_target ==> done ok (?P<gain_target>\d*\.\d*).*"
        )

    def parse_trx_map(self, raw_output):
        """
        Map tx to antenna

        :param raw_output: str
        :return: key: tx_id, value: antenna
        :rtype: dict
        """
        trx_map = {}
        [self._add_trx(line, trx_map) for line in raw_output.splitlines()]
        return trx_map

    def _add_trx(self, line, trx_map):
        match = self.re_trx_id.match(six.ensure_str(line, encoding="latin"))
        if match:
            trx_list = []
            for trx_id in match.group("trx_ids").split(" "):
                trx_list.append(trx_id)
            [
                trx_map.setdefault(trx.strip('"'), match.group("antenna"))
                for trx in trx_list
            ]

    def parse_tx_power(self, raw_output):
        """
        Map power to tx

        :param raw_output: str
        :return: key: tx_id, value: power
        :rtype: dict
        """
        tx_power = {}
        for line in raw_output.splitlines():
            match = self.re_power.match(six.ensure_str(line, encoding="latin"))
            if match:
                tx_power.setdefault(
                    match.group("tx_ids").strip('"'), match.group("power") or "OFF"
                )
        return tx_power

    def parse_rx_power(self, raw_output):
        """
        Map power to rx

        :param raw_output: str
        :return: key: rx_id, value: power
        :rtype: dict
        """
        rx_power = {}
        for line in raw_output.splitlines():
            match = self.re_rx_power.match(six.ensure_str(line, encoding="latin"))
            if match:
                rx_power.setdefault(
                    match.group("rx_ids").strip('"'), match.group("power") or "OFF"
                )
        return rx_power

    def parse_trx_carrier(self, raw_trx_carrier):
        """
        Map carrier info to antenna

        :param raw_trx_carrier: str
        :return: key: antenna number, value: dict with carrier info
        :rtype: dict
        """
        parsed_data = defaultdict(dict)
        trx_type = {"L": "LTE", "G": "GSM", "W": "WCDMA"}
        for line in raw_trx_carrier.splitlines():
            match = self.re_carrier.match(six.ensure_str(line, encoding="latin"))
            if match:
                trx_info = {
                    "frequency": float(match.group("frequency")) / 1000,
                    "type": trx_type[match.group("trx_ids")[0]],
                    "bandwidth": match.group("bandwidth"),
                    "state": match.group("state"),
                }
                parsed_data[match.group("antenna")][match.group("trx_ids")] = trx_info
        return parsed_data

    def parse_lna_device(self, raw_lna_device):
        parsed_lna_device = {}
        for line in raw_lna_device.splitlines():
            match = self.re_lna_device.match(six.ensure_str(line, encoding="latin"))
            if match:
                parsed_lna_device[int(match.group("rx_nr"))] = match.group("lna_nr")
        return parsed_lna_device

    def parse_gain_target(self, raw_gain_target):
        parsed_gain_target = 0
        for line in raw_gain_target.splitlines():
            match = self.re_gain_target.match(six.ensure_str(line, encoding="latin"))
            if match:
                parsed_gain_target = match.group("gain_target")
        return float(parsed_gain_target)
